  fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");
  fprintf(stderr, "Rendering high-resolution image...\n\n");
  int **img=(int**)malloc(H*sizeof(int*));
  for(int i=0;i<H;i++) img[i]=(int*)malloc(W*3*sizeof(int));
  Vec3 cam=vec3(0,0,1), llc=vec3(-1.33f,-1,-1), horiz=vec3(2.67f,0,0), vert=vec3(0,2,0);
  unsigned int seed=1;
  for(int j=0;j<H;j++) {
    if(j%6==0) fprintf(stderr, "Progress: %.1f%%\n", 100.0f*j/H);
    for(int i=0;i<W;i++) {
      Vec3 col=vec3(0,0,0);
      for(int s=0;s<2;s++) {
        seed=seed*1103515245+12345; float u=(i+(seed>>16&0x7fff)/32768.0f)/W;
        seed=seed*1103515245+12345; float v=(j+(seed>>16&0x7fff)/32768.0f)/H;
        Vec3 d=add(llc,add(mul(horiz,u),mul(vert,v)));
        col=add(col,trace(ray(cam,norm(d)),50,&seed));
      }
      col=mul(col,0.5f);
      img[j][i*3]=(int)(255*fmaxf(0,fminf(1,col.x)));
      img[j][i*3+1]=(int)(255*fmaxf(0,fminf(1,col.y)));
      img[j][i*3+2]=(int)(255*fmaxf(0,fminf(1,col.z)));
    }
  }
  fprintf(stderr, "Progress: 100.0%%\n");
  fprintf(stderr, "Rendering complete\n");
  FILE *f=fopen("image.ppm","w");
  fprintf(f,"P3\n%d %d\n255\n",W,H);
  for(int j=0;j<H;j++) for(int i=0;i<W;i++) fprintf(f,"%d %d %d\n",img[j][i*3],img[j][i*3+1],img[j][i*3+2]);
  fclose(f);
  fprintf(stderr, "Wrote image to image.ppm\n");
  fprintf(stderr, "Done.\n");
  return 0;
}
